    const availH = Math.max(1, vp.clientHeight);
    const scale = Math.min(availW / w, availH / h);
    const cssW = `${Math.max(1, Math.floor(w * scale))}px`;
    const cssH = `${Math.max(1, Math.floor(h * scale))}px`;
