    const key = subjectFeatureCacheKey(ctx);
    const cached = SUBJECT_FEATURE_CACHE.get(key);
    if(cached && cached.loading) return `<div class="rvSubjectPanelHeader"><b>${esc(ctx.caseId)}</b><span>Feature-level QC</span><span class="rvSubjectTag rvSubjectTagMuted">loading</span></div><div class="rvEmpty">${esc(cached.message || 'Loading...')}</div>`;
