    const visibleColumns = availableTableColumns(A, columns);
    const widths = tableColumnWidthSpec(visibleColumns, A);
    const colgroup = tableColGroupHtml(widths);
    const tableW = widths.reduce((acc,w) => acc + Number(w.width || 0), 0);
    const head = visibleColumns.map(c => `<th>${esc(c.label)}</th>`).join('');
