    const eligible=reportBuilderFeatureContextsForScope(state,modal).map(context=>({context,domain:authority.supportDomain([String(context&&context.featureKind||'')],context||{})})).filter(row=>row.domain&&arr(definition.supports).includes(row.domain));
    const imagingHasAtlas=imaging=>{const st=imaging&&typeof imaging==='object'?imaging:{},id=String(st.selectedAtlasId||'').trim().toLowerCase(),paths=st.surfaceAtlasPaths&&typeof st.surfaceAtlasPaths==='object'?st.surfaceAtlasPaths:{};return (!!id&&id!=='none')||[paths.selectedPath,paths.lhPath,paths.rhPath].some(value=>String(value||'').trim().length>0);};
