  function reportBuilderApplyRoiMapperConfiguration(state,modal,presentation){const p=presentation||state&&state.presentation||{},r=p.roiMapper=reportBuilderNormalizeRoiMapperState(p.roiMapper),cfg=reportBuilderRoiMapperConfiguration(state,modal,p);r.contextIds=cfg.contextIds.slice();state.roiComparisonKinds=cfg.comparisonKinds.slice();if(!cfg.available){r.enabled=false;r.comparisonKind='';return cfg;}if(r.enabled){const current=String(r.comparisonKind||'');r.comparisonKind=cfg.comparisonKinds.includes(current)?current:(cfg.comparisonKinds[0]||'payload');}return cfg;}

