  /**
   * reportBuilderInitialSelectedIds  Resolve default selected component ids from backend reportSpec.
   * It falls back to all enabled components when the default report specification does not contain a Components array.
   */
  function reportBuilderInitialSelectedIds(components, reportSpec){
    if(reportSpec && Object.prototype.hasOwnProperty.call(reportSpec,'Components')){
      return arr(reportSpec.Components).map(c => String(c.Id || '')).filter(Boolean);
    }
    return arr(components).filter(c => !!c.Enabled).map(c => String(c.Id || ''));
  }

  /**
   * reportBuilderMergeSelectedIds  Merge backend defaults with browser-derived selections while preserving catalogue order and availability.
   * This keeps non-feature default report sections selected while allowing the state-backed feature-inspection viewspace to replace the generic feature defaults.
   */
  function reportBuilderMergeSelectedIds(components, defaultIds, browserIds){
    const enabled = new Set(arr(components).filter(c => !!c.Enabled).map(c => String(c.Id || '')));
    const requested = new Set(arr(defaultIds).concat(arr(browserIds)).map(id => String(id || '')).filter(Boolean));
    const out = [];
    arr(components).forEach(c => {
      const id = String(c && c.Id || '');
      if(id && enabled.has(id) && requested.has(id) && out.indexOf(id) < 0) out.push(id);
    });
    return out;
  }

  /**
   * reportBuilderRemoveViewspaceIds  Drop component defaults for one viewspace so browser state can define that viewspace explicitly.
   * Model feature inspection uses this to avoid selecting all catalogue feature metrics when only the user's visible panels should be reproduced.
   */
  function reportBuilderRemoveViewspaceIds(components, ids, viewspace){
    const byId = new Map(arr(components).map(c => [String(c.Id || ''), c]));
    const target = String(viewspace || '');
    return arr(ids).map(id => String(id || '')).filter(id => {
      const c = byId.get(id);
      return c && String(c.Viewspace || '') !== target;
    });
  }

