    const available = new Set(arr(components).filter(c => !!c.Enabled).map(c => String(c.Id || '')));
    const ws = workspace();
    const ids = [];
    const add = id => { if(available.has(id) && ids.indexOf(id) < 0) ids.push(id); };
    const hasPanel = k => !!(ws && ws.querySelector(`.rvWorkspaceItem[data-kind="${k}"]:not(.isHidden)`));
    if(hasPanel('metrics')) add('model_performance.summary');
    if(hasPanel('classplot')) add('model_performance.primary_plot');
    if(hasPanel('confusion')) add('model_performance.confusion_matrix');
    if(hasPanel('roc')) add('model_performance.roc');
    if(hasPanel('pies')) add('model_performance.probability_distribution');
    syncModelPerformanceStateFromWorkspace();
    if(MODEL_PERFORMANCE_STATE.panels.calibration.visible) add('model_performance.calibration');
    if(MODEL_PERFORMANCE_STATE.panels.dca.visible) add('model_performance.dca');
