      overlay.innerHTML = `<div class="rvModalCard rvExportModal"><h3>${viewer?'Export viewer':'Export panel'}</h3><p>${viewer?'Export the currently rendered viewer scene together with its colour scale and presentation context.':`Export ${esc(artifactTitle||'the current '+panelRenderedKind(panel)+' panel')}. Vector/raster formats preserve the figure; table formats preserve its numerical data.`}</p><div class="rvExportGrid"><label>Format<select id="rvExportFormat">${formatOptions}</select></label>${qualityControls}</div><div id="rvExportHint" class="rvExportHint"></div><div class="rvModalActions"><button type="button" id="rvExportCancel">Cancel</button><button type="button" class="primary" id="rvExportGo">Export</button></div></div>`;
      document.body.appendChild(overlay);
