    const viewPagination=`<div class="rvFeatureRibbonSubgroup rvFeatureRibbonSubgroup--view"><label class="rvFeatureField rvFeatureField--selectLong">Sort<select data-feature-control="sortingMode" data-feature-metric="${esc(panelId)}"><option value="abs_desc"${st.sortingMode==='abs_desc'?' selected':''}>Joint magnitude, descending</option><option value="abs_asc"${st.sortingMode==='abs_asc'?' selected':''}>Joint magnitude, ascending</option><option value="feature_index"${st.sortingMode==='feature_index'?' selected':''}>Feature index</option><option value="label"${st.sortingMode==='label'?' selected':''}>Feature label</option></select></label></div><div class="rvFeatureRibbonSubgroup rvFeatureRibbonSubgroup--pagination"><label class="rvFeatureField rvFeatureField--spinner">Table rows<input data-feature-control="tableRowCount" data-feature-metric="${esc(panelId)}" type="number" min="1" max="500" step="1" value="${esc(st.tableRowCount)}"></label></div>`;
