  function featureSpatialOverlayPanelHtml(){
    if(!window.NMResultsViewerImagingViewer){
      return '<div class="rvSpatialOverlayPanel"><div class="rvPanelNotice">Imaging viewer asset NMResultsViewerImagingViewer.js is unavailable.</div></div>';
    }
    ensureFeatureInspectionState();
    const measures = window.NMResultsViewerImagingViewer.availableMeasures(PAYLOAD);
    if(!measures.length){
      const kinds=featureInspectionObservedFeatureKinds();
      const surfaceOnly=kinds.length>0&&kinds.every(k=>k==='surface_vertex');
      const reason=surfaceOnly
        ? 'The selected surface feature source exposes no enabled surface metric representation.'
        : 'The selected spatial feature source exposes no eligible voxel metric overlay.';
      return `<div class="rvSpatialOverlayPanel rvSpatialOverlayUnavailable"><div class="rvPanelNotice">${esc(reason)}</div><button id="rvOpenLegacyOverlayFromFeature" type="button">Open legacy Results Viewer</button></div>`;
    }
    return window.NMResultsViewerImagingViewer.shellHtml(measures, FEATURE_INSPECTION_STATE.imaging, esc);
  }

  /** Return a finite scalar without coercing JSON null to zero. */
