    if(FEATURE_CONNECTIVITY_EXTREMUM_FLASH_TIMER){window.clearTimeout(FEATURE_CONNECTIVITY_EXTREMUM_FLASH_TIMER);FEATURE_CONNECTIVITY_EXTREMUM_FLASH_TIMER=0;}
