    const id=String(payloadId||''),measures=window.NMResultsViewerImagingViewer.availableMeasures(PAYLOAD);
    FEATURE_INSPECTION_STATE.imaging.enabledMetricIds=measures.filter(measure=>measure&&measure.enabled!==false).map(measure=>measure.measureId).filter(Boolean);
    window.NMResultsViewerImagingViewer.activateMetric(FEATURE_INSPECTION_STATE.imaging,id,measures);
    FEATURE_INSPECTION_STATE.activeMetricId='connectivity_representation';
    renderFeatureInspectionToolbarMount();bindFeatureInspectionControls();
    const node=el('featureMetricPanel_connectivity_representation'),st=FEATURE_INSPECTION_STATE.panels&&FEATURE_INSPECTION_STATE.panels.connectivity_representation,retainGlass=!!(st&&st.connectivityView==='glass_brain'&&document.querySelector('[data-connectivity-glass-root]'));
