  /**
   * refreshState  Refresh the state page region after state or artifact availability changes.
   * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
   * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
   */
  async function refreshState(forceVectorOptions, requestSpec){
    const startedAt = performance.now();
    const requestId = ++STATE_REQUEST_SEQ;
    FEATURE_INSPECTION_FULL_PAYLOAD_REQUEST_SEQ += 1; FEATURE_INSPECTION_FULL_PAYLOAD_PENDING = null;
    PAYLOAD_REQUEST_SEQ += 1;
    VECTOR_OPTIONS_REQUEST_SEQ += 1;
    if(forceVectorOptions) invalidateViewContextCache('explicit refresh');
    const spec = requestSpec || selectedSpec();
    if(!forceVectorOptions && !spec.selectionTransition){
      const cacheStartedAt = performance.now();
      const cached = viewContextCacheLookup(spec);
      profileLog('view context cache lookup', cacheStartedAt, `hit=${cached ? 1 : 0} operation=state`);
      if(cached){
        if(requestId !== STATE_REQUEST_SEQ) return false;
        resetModelPermutationTransientState();
        STATE = cached.state;
        PAYLOAD = cached.payload;
        ACTIVE_SCIENTIFIC_STATE = cached.activeScientificState;
        PROFILE_ENABLED = !!STATE.profileEnabled || PROFILE_ENABLED;
        if(PAYLOAD && PAYLOAD.selectedSource) STATE.selectedSource = String(PAYLOAD.selectedSource);
        if(PAYLOAD && Number.isFinite(Number(PAYLOAD.selectedMultiClassModeIndex))) STATE.selectedMultiClassModeIndex = Number(PAYLOAD.selectedMultiClassModeIndex);
        renderPayload();
        await refreshOpenActionPanels('cached state restore', false);
        profileLog('refresh state', startedAt, `request=${requestId} cache=1`);
        return true;
      }
    }
    const res = await matlabService({operation:'results_viewer_alpha_refresh', spec, timeout:120});
    if(requestId !== STATE_REQUEST_SEQ) return false;
    if(!res||res.ok===false)throw new Error((res&&(res.message||res.error))||'Alpha Results Viewer refresh failed.');
    if(!res.state||typeof res.state!=='object'||!res.state.payload||typeof res.state.payload!=='object'||!res.state.payloadContext||typeof res.state.payloadContext!=='object'||!res.state.activeScientificState||String(res.state.activeScientificState.contractVersion||'')!=='NM-SCIENTIFIC-STATE-V1'||!Object.prototype.hasOwnProperty.call(res.state,'yAxisOptions')||!Object.prototype.hasOwnProperty.call(res.state,'multiClassModes')||!Object.prototype.hasOwnProperty.call(res.state,'oocvSubgroups'))throw new Error('Alpha Results Viewer refresh returned an incomplete scientific-state contract.');
    resetModelPermutationTransientState();
    STATE=res.state;PAYLOAD=STATE.payload;ACTIVE_SCIENTIFIC_STATE=STATE.activeScientificState;
    PROFILE_ENABLED=!!STATE.profileEnabled||PROFILE_ENABLED;
    if(PAYLOAD && PAYLOAD.selectedSource) STATE.selectedSource = String(PAYLOAD.selectedSource);
    if(PAYLOAD && Number.isFinite(Number(PAYLOAD.selectedMultiClassModeIndex)) && STATE) STATE.selectedMultiClassModeIndex = Number(PAYLOAD.selectedMultiClassModeIndex);
    renderPayload();
    if(!spec.selectionTransition) storeViewContextCache(spec,STATE.payloadContext,STATE,PAYLOAD,ACTIVE_SCIENTIFIC_STATE,'state refresh');
    profilePayloadFieldBytes(PAYLOAD, `state:${payloadKind()}`);
    await refreshOpenActionPanels('state refresh', !!forceVectorOptions);
    profileLog('refresh state', startedAt, `request=${requestId} cache=0`);
    return true;
  }
  /**
   * refreshPayload  Refresh or restore the payload for the active scientific context.
   * Optional plain-object overrides clear stale dependent selectors before cache lookup; DOM events are deliberately ignored as specifications. Side effects: may restore a cached context or send one request to the local MATLAB bridge and rerender browser state.
   */
  async function refreshPayload(overrides,preserveViewport){
    const viewportX=window.scrollX,viewportY=window.scrollY;
    const startedAt = performance.now();
    const requestId = ++PAYLOAD_REQUEST_SEQ;
    FEATURE_INSPECTION_FULL_PAYLOAD_REQUEST_SEQ += 1; FEATURE_INSPECTION_FULL_PAYLOAD_PENDING = null;
    const explicitOverrides = overrides && typeof overrides === 'object' && !overrides.type ? overrides : {};
    const spec = selectedSpec(explicitOverrides);
    if(String(spec.resultType||'').toLowerCase()==='model_feature_inspection' && !Object.prototype.hasOwnProperty.call(explicitOverrides,'featureInspectionPayloadScope')){
      spec.featureInspectionPayloadScope='metadata';
    }
    const cacheStartedAt = performance.now();
    const cached = viewContextCacheLookup(spec);
    profileLog('view context cache lookup', cacheStartedAt, `hit=${cached ? 1 : 0} operation=payload`);
    if(cached){
      if(requestId !== PAYLOAD_REQUEST_SEQ) return false;
      resetModelPermutationTransientState();
      PAYLOAD = cached.payload;
      if(STATE) STATE.payloadContext = cached.payloadContext;
      ACTIVE_SCIENTIFIC_STATE = cached.activeScientificState;
      if(PAYLOAD && PAYLOAD.selectedSource && STATE) STATE.selectedSource = String(PAYLOAD.selectedSource);
      if(PAYLOAD && Number.isFinite(Number(PAYLOAD.selectedMultiClassModeIndex)) && STATE) STATE.selectedMultiClassModeIndex = Number(PAYLOAD.selectedMultiClassModeIndex);
      renderPayload();
      if(preserveViewport)window.scrollTo(viewportX,viewportY);
      await refreshOpenActionPanels('cached payload restore', false);
      profileLog('refresh payload', startedAt, `request=${requestId} cache=1`);
      return true;
    }
    const res = await matlabService({operation:'results_viewer_alpha_payload', spec, timeout:120});
    if(requestId !== PAYLOAD_REQUEST_SEQ) return false;
    if(!res||res.ok===false)throw new Error((res&&(res.message||res.error))||'Results Viewer payload extraction failed.');
    if(!res.payload||typeof res.payload!=='object'||!res.payloadContext||typeof res.payloadContext!=='object'||!res.scientificState||typeof res.scientificState!=='object'||String(res.scientificState.contractVersion||'')!=='NM-SCIENTIFIC-STATE-V1')throw new Error('Results Viewer payload extraction returned an incomplete scientific context.');
    resetModelPermutationTransientState();
    PAYLOAD=res.payload;STATE.payloadContext=res.payloadContext;ACTIVE_SCIENTIFIC_STATE=res.scientificState;
    if(PAYLOAD && PAYLOAD.selectedSource && STATE) STATE.selectedSource = String(PAYLOAD.selectedSource);
    if(PAYLOAD && Number.isFinite(Number(PAYLOAD.selectedMultiClassModeIndex)) && STATE) STATE.selectedMultiClassModeIndex = Number(PAYLOAD.selectedMultiClassModeIndex);
    renderPayload();
    if(preserveViewport)window.scrollTo(viewportX,viewportY);
    storeViewContextCache(spec,res.payloadContext,STATE,PAYLOAD,ACTIVE_SCIENTIFIC_STATE,'payload refresh');
    profilePayloadFieldBytes(PAYLOAD, `payload:${payloadKind()}`);
    await refreshOpenActionPanels('payload refresh', false);
    profileLog('refresh payload', startedAt, `request=${requestId} cache=0`);
    return true;
  }
  /**
   * openLegacy  Open the legacy panel, dialog or linked UI target.
   * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
   * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
   */
  async function openLegacy(){
    const res = await matlabService({operation:'results_viewer_alpha_open_legacy', spec:selectedSpec(), timeout:120});
    if(!res || res.ok === false) throw new Error((res && (res.message || res.error)) || 'Opening legacy viewer failed.');
  }
  /**
   * finish  Provide the finish helper used by Results Viewer browser page for classification, regression, OOCV, QC and subject-level result inspection.
   * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
   * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
   */
  async function finish(){
    const ctx = (STATE && STATE.appContext) || {};
    if(String(ctx.caller || '').toLowerCase() === 'workbench'){
      try{
        const result=await matlabService({operation:'app_child_return',source:'results_viewer_alpha',timeout:120});
        if(!result || result.ok===false)throw new Error(result&&result.message||'Results Viewer return failed.');
        const launch=new URLSearchParams(window.location.search);
        if(launch.get('synthReturn')==='1'){
          const prepared=await matlabService({operation:'app_prepare_page',page:'synth_coordinator',moduleKey:'synth_coordinator',timeout:240});
          if(!prepared || prepared.ok===false)throw new Error(prepared&&prepared.message||'SYNTH page preparation failed.');
          const params=new URLSearchParams({port:String(PORT),synthTab:'execution',synthAnalysis:launch.get('synthAnalysis')||'0',_nmcb:String(Date.now())});
          const route=`${prepared.entryHtml}?${params}`;
          window.location.replace(window.NMBridgeNavigationURL?window.NMBridgeNavigationURL(route):route);
          return;
        }
      }catch(err){console.error('Results Viewer return navigation',err);setMsg(`Return navigation failed: ${err.message||String(err)}`,'danger');return;}
      window.location.replace(window.NMBridgeNavigationURL ? window.NMBridgeNavigationURL(`nm_workbench.html?port=${encodeURIComponent(PORT)}&_nmcb=${Date.now()}`) : `nm_workbench.html?port=${encodeURIComponent(PORT)}&_nmcb=${Date.now()}`);
    } else {
      setMsg('You can close this browser tab.', 'info');
    }
  }
  /**
   * toggleModelPerformanceTransform  Toggle one primary-plot transformation from the shared model-performance state.
   */
  function toggleModelPerformanceTransform(key){
    const map = {sort:'plotSort',swap:'colorSwap',ranks:'percentRank'};
    const optionKey = map[String(key || '')];
    if(!optionKey) return;
    VIEW_OPTIONS[optionKey] = !VIEW_OPTIONS[optionKey];
    if(optionKey === 'percentRank' && VIEW_OPTIONS[optionKey]) VIEW_OPTIONS.probTransform = false;
    renderPlotToolbar();
    refreshPayload().catch(err => setMsg(`Plot refresh failed: ${err.message || String(err)}`, 'danger'));
  }

  /**
   * toggleProbabilityTransform  Toggle score/probability rendering while preserving the established calibration workflow.
   */
  async function toggleProbabilityTransform(){
    const prob = el('probBtn');
    if(!prob || prob.disabled) return;
    if(VIEW_OPTIONS.probTransform){
      VIEW_OPTIONS.probTransform = false;
      renderPlotToolbar();
      refreshPayload().catch(err => setMsg(`Plot refresh failed: ${err.message || String(err)}`, 'danger'));
      return;
    }
    const choice = await showCalibrationDialog('Convert scores to probabilities', true);
    if(!choice) return;
    VIEW_OPTIONS.probMethod = choice.method || 'platt';
    VIEW_OPTIONS.probTransform = true;
    VIEW_OPTIONS.percentRank = false;
    renderPlotToolbar();
    try{
      const payload = await fetchActionPayload('probability', {calibrationMethod:VIEW_OPTIONS.probMethod, forceRecomputeProbability:!!choice.recompute});
      if(payload && payload.message) setMsg(payload.message, payload.didPersistProbability ? 'ok' : 'info');
    }catch(err){ setMsg(`Probability conversion failed: ${err.message || String(err)}`, 'danger'); }
    refreshPayload().catch(err => setMsg(`Plot refresh failed: ${err.message || String(err)}`, 'danger'));
  }

  /**
   * toggleCalibrationPanel  Add or remove the calibration panel without changing unrelated model-performance panels.
   */
  async function toggleCalibrationPanel(){
    const button = el('calibBtn');
    if(!button || button.disabled) return;
    if(MODEL_PERFORMANCE_STATE.panels.calibration.visible){
      removeWorkspacePanelsByKind(['calibration']);
      syncModelPerformanceStateFromWorkspace();
      renderPlotToolbar();

      return;
    }
    const choice = await showCalibrationDialog('Calibration analysis', false);
    if(!choice) return;
    try{
      VIEW_OPTIONS.probMethod = choice.method || 'platt';
      const payload = await fetchActionPayload('calibration', {calibrationMethod:VIEW_OPTIONS.probMethod, forceRecomputeProbability:!!choice.recompute, numBins:10, smoothCurve:false, calibrationMetric:'ECE'});
      const defs = workspaceDefaults(payloadKind());
      const panel = ensureWorkspacePanel('calibration', `Calibration — ${methodLabel(VIEW_OPTIONS.probMethod)}`, {rect:defs.calibration, closable:true, bodyHtml:'', actionKind:'calibration', actionMethod:VIEW_OPTIONS.probMethod, actionIdentity:actionIdentityKey('calibration', VIEW_OPTIONS.probMethod)});
      const wasCreated = !!(panel && panel.__rvWasCreated);
      renderCalibrationPanel(panel, payload);
      MODEL_PERFORMANCE_STATE.panels.calibration.visible = true;
      layoutWorkspaceAfterPanelChange();
      renderPlotToolbar();
      scheduleWorkspacePanelCreationNotice(wasCreated ? [panel] : [], 'The calibration panel was added outside the current view.');

    }catch(err){ setMsg(`Calibration panel failed: ${err.message || String(err)}`, 'danger'); }
  }

